# Standalone, deterministic, fail-closed. No imports, no I/O, no floats.
# Witness is embedded: range n in 2..200, construction x_j = (j,0).
# Exit 0 (no exception) only when every check passes; any mismatch raises.

def verify(witness):
    # witness schema check (fail closed on any deviation)
    if witness is None:
        raise RuntimeError('FAIL: no witness')
    if witness.get('construction') is None:
        raise RuntimeError('FAIL: construction missing')
    rng = witness.get('range')
    if (not isinstance(rng, list) or len(rng) != 2
            or not all(isinstance(t, int) for t in rng)
            or rng[0] != 2 or rng[1] != 200):
        raise RuntimeError('FAIL: unexpected range')
    lo, hi = rng
    for n in range(lo, hi + 1):
        pts = [(j, 0) for j in range(n)]
        if len(set(pts)) != n:
            raise RuntimeError('FAIL: points not distinct at n=%d' % n)
        # squared distances from x_0=(0,0), exact integers
        d = sorted(set((j) * (j) for j in range(1, n)))
        expected = sorted(k * k for k in range(1, n))
        if d != expected:
            raise RuntimeError('FAIL: distance set mismatch at n=%d' % n)
        if len(d) != n - 1:
            raise RuntimeError('FAIL: cardinality mismatch at n=%d' % n)
    return True

EMBEDDED_WITNESS = {
    'construction': 'x_j = (j,0), j=0..n-1; endpoint distances {1,..,n-1}',
    'range': [2, 200],
}

if not verify(EMBEDDED_WITNESS):
    raise RuntimeError('FAIL')
